import{_ as o,l as n,o as a,c as l,v as t,p as i,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"可持久化线段树","description":"","frontmatter":{"title":"可持久化线段树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/persistent-segment-tree.md","filePath":"cs/persistent-segment-tree.md","lastUpdated":1789023840000}'),h={name:"cs/persistent-segment-tree.md"};function m(_,e,u,A,f,E){const s=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="可持久化线段树" tabindex="-1">可持久化线段树 <a class="header-anchor" href="#可持久化线段树" aria-label="Permalink to &quot;可持久化线段树&quot;">​</a></h1><div class="epigraph"><p>每次修改只复制根到叶的 $O(\\log n)$ 个新节点，旧根仍指向未改的子树；版本是一条根指针。</p><footer>—— 据 Driscoll, Sarnak, Sleator and Tarjan, Making Data Structures Persistent, JCSS 1989；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/segment-tree-lazy">上一课</a>让同一棵树在更新后丢掉旧聚合。若还要问「第 \\(k\\) 次修改之前 \\([l,r]\\) 的和」，就得把历史留下来。本课不重讲懒标记复合。缺口是可持久化（主席树常用形态）：路径复制，每版本 \\(O(\\log n)\\) 新节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>函数式与回溯、整体二分、区间第 \\(k\\) 小，都需要多份数组快照。整表复制每次 \\(\\Theta(n)\\)。缺口是：<strong>共享未改子树</strong>。修改 \\(A[i]\\)：新建叶与祖先，左右孩子指针能指旧节点的就指旧的。每个版本一个根。查询带着根走，语义与普通线段树相同，只是读的是那一版。</p><p><span class="marginnote">Driscoll et al. 区分部分/完全持久与函数式（只出新版本）。主席树是函数式线段树的竞赛名，本课用路径复制说话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建版本 \\(0\\) 与建普通树相同。从版本 \\(v\\) 改点 \\(i\\) 得版本 \\(v+1\\)：递归时若区间不含 \\(i\\) 则返回旧节点指针；含 \\(i\\) 则 <code>new</code> 一个节点，一边接递归结果，一边接旧孩子。空间对 \\(m\\) 次修改是 \\(O(n+m\\log n)\\)。查询 \\(O(\\log n)\\)，不写回。</p>',8)),(a(),i(c,null,{default:r(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%22%5D%20--%3E%20SHARE%5B%22%E6%9C%AA%E6%94%B9%E5%AD%90%E6%A0%91%E5%85%B1%E4%BA%AB%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%20--%3E%20PATH%5B%22O(log%20n)%20%E6%96%B0%E8%8A%82%E7%82%B9%22%5D%0A%20%20PATH%20--%3E%20SHARE%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>懒标记与可持久化可以同时做，但标记下传会被迫复制孩子，常数与正确性更烦；本课默认点修可持久化，不把懒标持久化写完。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>旧根可达的节点永不原地改，否则历史被污染。这要求分配新节点，不能在数组线段树里覆写 \\(2u\\)。动态开点：若值域大、实际点少，节点按需 <code>new</code>，同一套复制。区间第 \\(k\\) 小：权值线段树每个前缀一个版本，两点根相减得区间频次——那是应用，机制仍是版本差。</p><p>与后课<a href="/cs/persistent-path-copy">路径复制</a>同一思想，本课先在线段树上落地。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把并查集可持久化、或 fat node 的完全持久写进来。空间随版本线性涨，不能当无限日志。并发多写者抢同一版本链需要后课无锁/持久化另一套语言。</p><p>后课默认：要历史区间聚合，持有旧根。单次扫描上的近邻结构，用单调栈队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可持久化线段树：改路径复制，\\(O(\\log n)\\) 新节点/版本。</li><li>旧根只读；原地写会毁掉历史。</li><li>下一缺口是线性扫描里的近邻，不是更多版本。</li><li>出处：Driscoll et al., <em>JCSS</em>, 1989；Okasaki。</li></ul>',9))])}const g=o(h,[["render",m]]);export{T as __pageData,g as default};
